#!/usr/bin/env python3
"""Read-only TPL GitHub monitor. Produces a timestamped report and JSON snapshot."""
from __future__ import annotations

import json
import os
import re
import sys
import urllib.error
import urllib.parse
import urllib.request
from datetime import datetime
from pathlib import Path
from zoneinfo import ZoneInfo

API = "https://api.github.com"
REPO = os.environ["GITHUB_REPOSITORY"]
TOKEN = os.environ["GITHUB_TOKEN"]
TZ = ZoneInfo("America/Sao_Paulo")
WARNINGS: list[str] = []


def api_get(url: str):
    if url.startswith("/"):
        url = API + f"/repos/{REPO}" + url
    req = urllib.request.Request(
        url,
        headers={
            "Accept": "application/vnd.github+json",
            "Authorization": f"Bearer {TOKEN}",
            "X-GitHub-Api-Version": "2022-11-28",
            "User-Agent": "TPL-read-only-monitor",
        },
        method="GET",
    )
    try:
        with urllib.request.urlopen(req, timeout=25) as response:
            body = response.read().decode("utf-8")
            return json.loads(body) if body else None, response.headers.get("Link", "")
    except urllib.error.HTTPError as exc:
        detail = exc.read().decode("utf-8", errors="replace")[:300]
        WARNINGS.append(f"HTTP {exc.code} em {url}: {detail}")
    except Exception as exc:
        WARNINGS.append(f"Falha ao consultar {url}: {type(exc).__name__}: {exc}")
    return None, ""


def pages(path: str, key: str | None = None):
    url = path
    items = []
    while url:
        payload, link_header = api_get(url)
        if payload is None:
            break
        page_items = payload.get(key, []) if key and isinstance(payload, dict) else payload
        if isinstance(page_items, list):
            items.extend(page_items)
        else:
            WARNINGS.append(f"Formato inesperado ao paginar {url}")
            break
        match = re.search(r'<([^>]+)>;\s*rel="next"', link_header)
        url = match.group(1) if match else ""
    return items


def short_sha(value: str | None) -> str:
    return value[:12] if value else "ausente"


def fmt_time(value: str | None) -> str:
    if not value:
        return "sem data"
    try:
        dt = datetime.fromisoformat(value.replace("Z", "+00:00")).astimezone(TZ)
        return dt.strftime("%Y-%m-%d %H:%M:%S -03")
    except Exception:
        return value


def text_line(value: str) -> str:
    return (value or "").replace("\r", " ").replace("\n", " ").strip()


now = datetime.now(TZ)
stamp = now.strftime("%Y%m%d_%H%M")
display_time = now.strftime("%Y-%m-%d %H:%M:%S -03")
outdir = Path("out")
outdir.mkdir(exist_ok=True)

# Canonical branch and documents
main_branch, _ = api_get("/branches/main")
main_sha = (main_branch or {}).get("commit", {}).get("sha")
canonical = {}
for path in ("TPL_CANONE.md", "tpl_estado.json"):
    item, _ = api_get("/contents/" + path + "?ref=main")
    canonical[path] = {
        "sha": (item or {}).get("sha"),
        "size": (item or {}).get("size"),
        "download_url": (item or {}).get("download_url"),
    }


# Detectar nomes de modelos em arquivos textuais do repositório.
# Isto é apenas um alerta de revisão: não reescreve autoria nem altera arquivos.
MODEL_NAME_RE = re.compile(r"\b(Claude|ChatGPT|GPT[- ]?\d*|Gemini|Copilot|Meta AI|OpenAI)\b", re.IGNORECASE)
AUTHOR_CONTEXT_RE = re.compile(
    r"\b(AUTOR|AUTHOR|ASSINADO|SIGNED|CRIADO POR|CREATED BY|GERADO POR|GENERATED BY)\b",
    re.IGNORECASE,
)
tree_payload, _ = api_get(f"/git/trees/{main_sha}?recursive=1")
model_name_findings = []
tree_entries = (tree_payload or {}).get("tree", [])
if (tree_payload or {}).get("truncated"):
    WARNINGS.append("Árvore Git truncada: a varredura de nomes de modelos pode estar incompleta.")
text_extensions = {".md", ".txt", ".json", ".py", ".yml", ".yaml", ".toml", ".rst", ".csv"}
for entry in tree_entries:
    path = entry.get("path", "")
    if entry.get("type") != "blob" or Path(path).suffix.lower() not in text_extensions:
        continue
    if path.startswith(".git/") or path.startswith("out/"):
        continue
    file_payload, _ = api_get("/contents/" + urllib.parse.quote(path, safe="/") + "?ref=main")
    if not file_payload or file_payload.get("encoding") != "base64":
        continue
    try:
        file_text = __import__("base64").b64decode(file_payload.get("content", "")).decode("utf-8")
    except Exception:
        continue
    for line_number, line in enumerate(file_text.splitlines(), 1):
        for match in MODEL_NAME_RE.finditer(line):
            model_name_findings.append({
                "path": path,
                "line": line_number,
                "model_name": match.group(0),
                "possible_attribution": bool(AUTHOR_CONTEXT_RE.search(line)),
                "excerpt": line.strip()[:240],
            })

commits = pages("/commits?sha=main&per_page=5")
open_prs = pages("/pulls?state=open&per_page=100")
open_pr_numbers = {p.get("number") for p in open_prs}
tracked_numbers = sorted(open_pr_numbers.union({13, 14, 16, 17}))
prs = []
for number in tracked_numbers:
    pr, _ = api_get(f"/pulls/{number}")
    if not pr:
        continue
    files = pages(f"/pulls/{number}/files?per_page=100")
    head_sha = (pr.get("head") or {}).get("sha")
    runs_payload, _ = api_get(
        "/actions/runs?" + urllib.parse.urlencode({"head_sha": head_sha or "", "per_page": 20})
    )
    runs = (runs_payload or {}).get("workflow_runs", [])[:5]
    run_records = []
    for run in runs:
        jobs = pages(f"/actions/runs/{run.get('id')}/jobs?per_page=100", "jobs")
        counts = {}
        failed_jobs = []
        for job in jobs:
            conclusion = job.get("conclusion") or job.get("status") or "unknown"
            counts[conclusion] = counts.get(conclusion, 0) + 1
            if conclusion not in ("success", "skipped"):
                bad_steps = [
                    s.get("name", "step")
                    for s in (job.get("steps") or [])
                    if s.get("conclusion") not in (None, "success", "skipped")
                ]
                failed_jobs.append({
                    "name": job.get("name"),
                    "conclusion": conclusion,
                    "failed_steps": bad_steps,
                })
        run_records.append({
            "id": run.get("id"),
            "name": run.get("name"),
            "run_number": run.get("run_number"),
            "event": run.get("event"),
            "status": run.get("status"),
            "conclusion": run.get("conclusion"),
            "head_sha": run.get("head_sha"),
            "created_at": run.get("created_at"),
            "url": run.get("html_url"),
            "jobs_total": len(jobs),
            "job_counts": counts,
            "failed_jobs": failed_jobs,
        })
    prs.append({
        "number": number,
        "title": pr.get("title"),
        "state": pr.get("state"),
        "draft": pr.get("draft"),
        "merged": pr.get("merged"),
        "updated_at": pr.get("updated_at"),
        "url": pr.get("html_url"),
        "base": (pr.get("base") or {}).get("ref"),
        "head_branch": (pr.get("head") or {}).get("ref"),
        "head_sha": head_sha,
        "body": pr.get("body") or "",
        "files": [
            {
                "filename": f.get("filename"),
                "status": f.get("status"),
                "changes": f.get("changes"),
            }
            for f in files
        ],
        "runs": run_records,
    })

snapshot = {
    "generated_at": display_time,
    "repository": REPO,
    "main_sha": main_sha,
    "canonical": canonical,
    "model_name_findings": model_name_findings,
    "recent_commits": [
        {
            "sha": c.get("sha"),
            "message": text_line((c.get("commit") or {}).get("message", "").split("\n")[0]),
            "date": ((c.get("commit") or {}).get("committer") or {}).get("date"),
            "url": c.get("html_url"),
        }
        for c in commits
    ],
    "open_pull_requests": [
        {
            "number": p.get("number"),
            "title": p.get("title"),
            "url": p.get("html_url"),
            "updated_at": p.get("updated_at"),
        }
        for p in open_prs
    ],
    "tracked_pull_requests": prs,
    "warnings": WARNINGS,
}

lines = [
    f"[ORIGEM: GitHub Actions — {display_time}]",
    "",
    "[0] PERMANECE",
    f"- Repositório: https://github.com/{REPO}",
    f"- main: {main_sha or 'não consultado'}",
]
for path, item in canonical.items():
    lines.append(f"- {path}: blob {item.get('sha') or 'não consultado'}")
lines.append("- Fonte de estado: TPL_CANONE.md e tpl_estado.json em main.")

lines.append("")
lines.append("[VARREDURA DE AUTORIA — NOMES DE MODELOS]")
possible_authorship = [x for x in model_name_findings if x["possible_attribution"]]
if possible_authorship:
    lines.append(f"- ALERTA: {len(possible_authorship)} ocorrência(s) em contexto semelhante a autoria/assinatura:")
    for item in possible_authorship:
        lines.append(f"  - {item['path']}:{item['line']} — {item['model_name']} — {item['excerpt']}")
else:
    lines.append("- Nenhuma ocorrência encontrada em contexto semelhante a autoria/assinatura na varredura textual.")
if model_name_findings:
    lines.append(f"- Total de menções a nomes de modelos em arquivos textuais: {len(model_name_findings)}.")
    lines.append("- Menções em testes, exemplos e registros são separadas de possíveis assinaturas; exigem revisão humana.")
else:
    lines.append("- Nenhuma menção a nomes de modelos encontrada nos arquivos textuais examinados.")

lines.append("")
lines.append("[1] MUDOU")
lines.append("- Fotografia atual; não infere diferenças em relação a um relatório anterior.")
if snapshot["recent_commits"]:
    lines.append("- Cinco commits recentes (ou menos) em main:")
    for c in snapshot["recent_commits"]:
        lines.append(f"  - {c['sha']} — {c['date']} — {c['message']} — {c['url']}")
else:
    lines.append("- Nenhum commit recente pôde ser recuperado.")
lines.append(f"- PRs abertos encontrados: {len(open_prs)}.")
for pr in sorted(prs, key=lambda x: x["number"]):
    status = "rascunho" if pr["draft"] else "aberto"
    if pr["state"] != "open":
        status = "integrado" if pr["merged"] else pr["state"]
    lines.append(
        f"  - #{pr['number']} [{status}] {text_line(pr['title'] or '')}; "
        f"branch {pr['head_branch']}; head {short_sha(pr['head_sha'])}; "
        f"atualizado {fmt_time(pr['updated_at'])}; {pr['url']}"
    )
    if pr["files"]:
        file_names = ", ".join(f["filename"] for f in pr["files"])
        lines.append(f"    arquivos: {file_names}")
    else:
        lines.append("    arquivos: não recuperados/nenhuma alteração listada")
lines.append("")
lines.append("[2] EVIDÊNCIA")
for pr in sorted(prs, key=lambda x: x["number"]):
    lines.append(f"- PR #{pr['number']}:")
    if not pr["runs"]:
        lines.append("  - Nenhuma execução associada ao head foi recuperada.")
    for run in pr["runs"]:
        counts = ", ".join(f"{k}={v}" for k, v in sorted(run["job_counts"].items())) or "sem jobs retornados"
        lines.append(
            f"  - {run['name']} #{run['run_number']} (ID {run['id']}): "
            f"{run['status']}/{run['conclusion']}; jobs={run['jobs_total']} ({counts}); "
            f"commit={short_sha(run['head_sha'])}; evento={run['event']}; "
            f"{run['url']}"
        )
        for failed in run["failed_jobs"]:
            steps = ", ".join(failed["failed_steps"]) or "etapa não identificada"
            lines.append(f"    FALHA: {failed['name']} — {failed['conclusion']}; etapas: {steps}")
lines.append("")
lines.append("[3] FALHAS-LIMITES")
if WARNINGS:
    for warning in WARNINGS:
        lines.append(f"- Coleta incompleta: {warning}")
else:
    lines.append("- Nenhum erro de consulta à API foi registrado nesta coleta.")
lines.append("- Resultado verde vale somente para o commit, ambiente, workflow e jobs efetivamente executados.")
lines.append("- Autoteste e malha na mesma infraestrutura não são, por si, evidência INDEPENDENTE.")
lines.append("- Este relatório é uma fotografia; não compara automaticamente com a fotografia anterior.")
lines.append("- Operação somente leitura: não altera arquivos, branches, PRs, configurações ou estados.")
lines.append("")
lines.append("[4] PRÓXIMA AÇÃO")
lines.append("- Para P-01/P-02, confrontar cada afirmação do PR #13 com a implementação e os testes de regressão do PR #16; não encerrar achado somente por check verde.")
lines.append("- Manter a escada epistemológica do TPL e não promover AUTOMEDIÇÃO para REPRODUZIDO ou INDEPENDENTE sem a evidência correspondente.")
lines.append("")
lines.append("Nota de coleta: um dado ausente ou uma consulta incompleta não é prova de inexistência nem de sucesso.")

report = "\n".join(lines) + "\n"
report_path = outdir / f"ENTRADA_GITHUB_{stamp}.txt"
snapshot_path = outdir / f"ESTADO_GITHUB_{stamp}.json"
report_path.write_text(report, encoding="utf-8")
snapshot_path.write_text(json.dumps(snapshot, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
print(f"Relatório: {report_path}")
print(f"Snapshot: {snapshot_path}")
print(report)
if WARNINGS:
    print(f"Coleta com {len(WARNINGS)} aviso(s).", file=sys.stderr)
